use std::path::PathBuf;

use serde::{Deserialize, Serialize};

/// Crate-wide result type.
pub type Result<T> = std::result::Result<T, Error>;

/// Crate-wide error type.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("capture failed: {0}")]
    Capture(String),

    #[error("encode failed: {0}")]
    Encode(String),

    #[error("config error: {0}")]
    Config(String),

    #[error("hotkey error: {0}")]
    Hotkey(String),

    #[error("io error: {0}")]
    Io(#[from] std::io::Error),

    #[error("{0}")]
    Other(String),
}

/// A rectangle in **virtual-desktop pixel coordinates**.
///
/// `x`/`y` may be negative on multi-monitor setups (monitors left of / above
/// the primary monitor). Coordinates are physical pixels, NOT DPI-scaled logical
/// units — callers must convert from logical to physical where needed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Rect {
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
}

impl Rect {
    pub fn new(x: i32, y: i32, width: u32, height: u32) -> Self {
        Self { x, y, width, height }
    }

    /// `true` when the rectangle has zero area.
    pub fn is_empty(&self) -> bool {
        self.width == 0 || self.height == 0
    }
}

/// A captured raster image.
///
/// Pixel buffer is **BGRA8, top-down**, tightly packed:
/// `bgra.len() == width as usize * height as usize * 4`, row stride = `width * 4`.
/// Byte order within a pixel is Blue, Green, Red, Alpha. This matches the native
/// Windows GDI / DXGI layout so no per-pixel swizzle is needed on capture.
#[derive(Clone)]
pub struct CapturedImage {
    pub width: u32,
    pub height: u32,
    pub bgra: Vec<u8>,
}

impl CapturedImage {
    pub fn new(width: u32, height: u32, bgra: Vec<u8>) -> Self {
        debug_assert_eq!(bgra.len(), width as usize * height as usize * 4);
        Self { width, height, bgra }
    }
}

/// Output file format for a saved capture.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ImageFormat {
    Png,
    Jpg,
}

impl ImageFormat {
    /// File extension without the dot: `"png"` / `"jpg"`.
    pub fn ext(&self) -> &'static str {
        match self {
            ImageFormat::Png => "png",
            ImageFormat::Jpg => "jpg",
        }
    }
}

/// One pre-configured capture region bound to a global hotkey.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Preset {
    /// Stable unique id (e.g. a UUID or slug). Never reused.
    pub id: String,
    /// Human-readable name shown in the UI and usable in filename templates.
    pub name: String,
    /// The fixed region to capture, in virtual-desktop physical pixels.
    pub region: Rect,
    /// Global hotkey string, parseable by `global-hotkey`
    /// (e.g. `"Ctrl+Shift+1"`, `"Alt+F2"`). Empty string = no hotkey bound.
    pub hotkey: String,
    /// Per-preset overrides. When `None`, the matching `Settings` default applies.
    pub format: Option<ImageFormat>,
    pub quality: Option<u8>,
    pub output_dir: Option<PathBuf>,
    pub filename_template: Option<String>,
}

/// Where a toast appears on screen.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ToastCorner {
    TopLeft,
    TopRight,
    BottomLeft,
    BottomRight,
}

/// What a mouse click on the toast does.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ToastAction {
    None,
    OpenFile,
    OpenFolder,
    CopyPath,
    /// Permanently delete the saved file (no confirmation).
    DeleteFile,
}

/// Fully customizable toast configuration (ShareX-style notification).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToastConfig {
    pub enabled: bool,
    pub corner: ToastCorner,
    /// Toast window size in physical pixels.
    pub width: u32,
    pub height: u32,
    /// Gap from the screen edge in pixels.
    pub margin: i32,
    /// How long the toast stays fully visible, milliseconds.
    pub duration_ms: u32,
    /// Fade-in / fade-out duration, milliseconds.
    pub fade_ms: u32,
    /// Show a thumbnail of the captured image inside the toast.
    pub show_thumbnail: bool,
    pub left_click: ToastAction,
    pub right_click: ToastAction,
    pub middle_click: ToastAction,
}

impl Default for ToastConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            corner: ToastCorner::BottomRight,
            width: 400,
            height: 300,
            margin: 16,
            duration_ms: 2000,
            fade_ms: 120,
            show_thumbnail: true,
            left_click: ToastAction::OpenFile,
            right_click: ToastAction::OpenFolder,
            middle_click: ToastAction::CopyPath,
        }
    }
}

/// Top-level persisted application settings.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Settings {
    pub presets: Vec<Preset>,
    pub default_output_dir: PathBuf,
    /// Filename template, see `naming` module for supported tokens.
    pub default_filename_template: String,
    pub default_format: ImageFormat,
    /// 1..=100. For JPG this is quality; for PNG it is a compression hint.
    pub default_quality: u8,
    pub toast: ToastConfig,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            presets: Vec::new(),
            default_output_dir: default_pictures_dir(),
            default_filename_template: "XerahS_%Y-%m-%d_%H-%M-%S_%n".to_string(),
            default_format: ImageFormat::Png,
            default_quality: 90,
            toast: ToastConfig::default(),
        }
    }
}

/// Best-effort default capture output directory (`%USERPROFILE%\Pictures\XerahS`).
pub fn default_pictures_dir() -> PathBuf {
    let base = std::env::var_os("USERPROFILE")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    base.join("Pictures").join("XerahS")
}

/// Context passed to the filename renderer. The renderer itself supplies the
/// current time (via `chrono`), so time is intentionally NOT part of this struct.
#[derive(Debug, Clone)]
pub struct NameContext {
    /// Name of the preset that triggered the capture.
    pub preset_name: String,
    /// Monotonic per-run counter used by the `%n` token.
    pub counter: u32,
    /// Title of the foreground window at capture time, if available.
    pub window_title: Option<String>,
    /// Captured image dimensions in pixels.
    pub width: u32,
    pub height: u32,
    /// File extension without dot (e.g. `"png"`); fills the `%ext` token.
    pub ext: String,
}
